import networkx as nx
from itertools import product

def roman_domination_number(G):
    n = G.number_of_nodes()
    nodes = list(G.nodes())
    # We can use MIP or brute force for small n
    best = 2 * n
    for f in product([0, 1, 2], repeat=n):
        # check if f is Roman dominating
        # for every v with f(v) == 0, exists u in N(v) with f(u) == 2
        valid = True
        for i, v in enumerate(nodes):
            if f[i] == 0:
                if not any(f[nodes.index(u)] == 2 for u in G.neighbors(v)):
                    valid = False
                    break
        if valid:
            cost = sum(f)
            if cost < best:
                best = cost
    return best

def check_graph(G):
    if not nx.is_connected(G) or G.number_of_nodes() < 2:
        return
    r = nx.radius(G)
    rd = roman_domination_number(G)
    if r + 1 > rd:
        print(f'Counterexample found! n={G.number_of_nodes()}, edges={list(G.edges())}, r={r}, rd={rd}')
        return True
    return False

found = False
for n in range(2, 8):
    print(f'Testing n={n}...')
    for G in nx.graph_atlas_g():
        if G.number_of_nodes() == n:
            if check_graph(G):
                found = True
                break
    if found:
        break
if not found:
    print('No counterexample in graph atlas (up to n=7)')
